This site has no robots.txt, so the check returns TRUE. Silence is not consent: you may scrape here because the site says it is a sandbox.

Block A — the sandbox

parse_books &lt;- function(pg) {
  pods &lt;- html_elements(pg, "article.product_pod") # 20 books
  tibble(
    title = pods |&gt; html_element("h3 a") |&gt; html_attr("title"),
    price = pods |&gt; html_element(".price_color") |&gt; html_text2(),
    rating = pods |&gt; html_element(".star-rating") |&gt; html_attr("class"),
    stock = pods |&gt; html_element(".availability") |&gt; html_text2()
  )
}
pg1 &lt;- nod(session, "catalogue/page-1.html") |&gt; scrape()

books1 &lt;- parse_books(pg1)

books1

html_elements() finds the books; html_element() — singular — returns exactly one value per book, and NA when it is missing. That keeps the columns aligned.

stars &lt;- c("One", "Two", "Three", "Four", "Five")
clean_books &lt;- function(df) {
  df |&gt; mutate(
    price = parse_number(price), # "£51.77" -&gt; 51.77
    rating = match(str_remove(rating, "star-rating "), stars),
    in_stock = str_detect(stock, "In stock")
  ) |&gt; select(-stock)
}
clean_books(books1)


get_page &lt;- function(i) {
  nod(session, paste0("catalogue/page-", i, ".html")) |&gt;
    scrape() |&gt; parse_books() |&gt; mutate(page = i)
}
books_raw &lt;- map(1:5, get_page) |&gt; list_rbind() # waits 5 s a page
dir.create("data", showWarnings = FALSE)
write_csv(books_raw, "data/books_raw.csv") # cache the raw pull

books &lt;- clean_books(books_raw)

