rectangle &lt;- function(quote_list) {
  tibble(q = quote_list) |&gt;
    unnest_wider(q) |&gt; # author, tags, text
    hoist(author, author_name = "name", author_slug = "slug") |&gt;
    mutate(tags = map_chr(tags, 
                          \(x) paste(unlist(x), collapse = "; "))) |&gt;
    select(text, author_name, author_slug, tags)

}
