6. Calculate the Rent-Burden Rate
The denominator is the total number of renter-occupied households. I divide the number of households spending 30% or more of income on rent by the total number of renter households.

acs_wide &lt;- acs_wide |&gt;
  mutate(
    burden_rate = burden_30_plusE / rentersE
  )

I then convert the rate to a percentage for easier interpretation.

acs_wide &lt;- acs_wide |&gt;
  mutate(
    burden_pct = burden_rate * 100
  )

7. Carry the Margin of Error Through the Calculation
Because the numerator combines four ACS estimates, I first calculate its margin of error using moe_sum().

acs_wide &lt;- acs_wide |&gt;
  rowwise() |&gt;
  mutate(
    burden_30_plusM = moe_sum(
      c(
        burden_30_35M,
        burden_35_40M,
        burden_40_50M,
        burden_50_plusM
      ),
      estimate = c(
        burden_30_35E,
        burden_35_40E,
        burden_40_50E,
        burden_50_plusE
      )
    )
  ) |&gt;
  ungroup()

I then use moe_prop() to carry the uncertainty through the calculation of the rent-burden rate.

acs_wide &lt;- acs_wide |&gt;
  mutate(
    burden_moe = moe_prop(
      burden_30_plusE,
      rentersE,
      burden_30_plusM,
      rentersM
    ),
    burden_moe_pct = burden_moe * 100
  )

3.3. Downloading the ten PDFs
The following function retrieves the PDF link from each package summary, downloads the file, and records whether the download succeeded. It also records errors so that failed requests can be investigated rather than silently ignored.
I was having trupiuble downloading the PDFs because they didn’t seem to be available as easily as the manual, hence I downloaded the zip fails which include the PDFs.

get_zip_link &lt;- function(summary) {
  links &lt;- summary$download

  if (is.null(links) || is.null(links$zipLink)) {
    return(NA_character_)
  }

  links$zipLink
}

download_hearing &lt;- function(package_id, title) {
  tryCatch({
    summary &lt;- get_package_summary(package_id)
    zip_url &lt;- get_zip_link(summary)

    if (is.na(zip_url) || !nzchar(zip_url)) {
      stop("No ZIP link was available.")
    }

    # Append the API key to the ZIP URL
    zip_url &lt;- paste0(
      zip_url,
      if (grepl("\\?", zip_url)) "&" else "?",
      "api_key=",
      api_key
    )

    file_path &lt;- file.path(
      download_dir,
      paste0(package_id, ".zip")
    )

    request(zip_url) |&gt;
      req_perform(path = file_path)

    tibble(
      packageId = package_id,
      title = title,
      file = file_path,
      status = "success",
      error = NA_character_
    )
  }, error = function(e) {
    tibble(
      packageId = package_id,
      title = title,
      file = NA_character_,
      status = "failed",
      error = conditionMessage(e)
    )
  })
}

download_log &lt;- purrr::map2_dfr(
  latest_hearings$packageId,
  latest_hearings$title,
  download_hearing
